import React from 'react';

import type { CSSObject } from '@emotion/react';

import { StyledCard } from './Card.styles';

export type CardElevation = 'minimal' | 'small' | 'medium' | 'large' | 'xlarge';
export type CardBorder = 'none' | 'small' | 'medium' | 'large';

export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  elevated?: CardElevation;
  border?: CardBorder;
  css?: CSSObject;
}

export const Card = React.forwardRef<HTMLDivElement, CardProps>(
  (
    { elevated = 'medium', border = 'medium', css, children, ...props },
    forwardedRef,
  ) => (
    <StyledCard
      {...props}
      ref={forwardedRef}
      $border={border}
      $css={css}
      $elevated={elevated}
    >
      {children}
    </StyledCard>
  ),
);

Card.displayName = 'Card';
